kIn = input(7, "K Neighbors", 1, 15, 1)
featureBars = input(20, "Feature Bars", 5, 40, 1)
searchBars = input(300, "Search Bars", 30, 500, 10)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
agreeThresh = input(0.35, "Max Disagreement", 0.05, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Model calculations: KNN-7 direction vote on returns ───
// Feature return r at lag L: (close[L] - close[L+1]) / close[L+1]
maxAvail = bar_index - featureBars - 1
searchLen = searchBars
if maxAvail < searchLen { searchLen := maxAvail }
if searchLen < 0 { searchLen := 0 }

// best-7 neighbour slots, recomputed every bar (plain assignments)
bestD1 = 999999.0
bestD2 = 999999.0
bestD3 = 999999.0
bestD4 = 999999.0
bestD5 = 999999.0
bestD6 = 999999.0
bestD7 = 999999.0
bestDir1 = 0
bestDir2 = 0
bestDir3 = 0
bestDir4 = 0
bestDir5 = 0
bestDir6 = 0
bestDir7 = 0

s = 1
while s <= searchLen {
    // Euclidean distance between current 20-return window and window at shift s
    sumSq = 0.0
    p = 0
    while p < featureBars {
        curA = close[p]
        curB = close[p + 1]
        pastA = close[s + p]
        pastB = close[s + p + 1]
        curR = (curA - curB) / (curB + 0.000000001)
        pastR = (pastA - pastB) / (pastB + 0.000000001)
        diff = curR - pastR
        sumSq := sumSq + diff * diff
        p := p + 1
    }
    // neighbour label = next-bar outcome after past bar j (j+1 vs j)
    d = 0 - 1
    if close[s - 1] > close[s] { d := 1 }
    // sorted insert into best-7 (smallest distance first)
    if sumSq < bestD1 {
        bestD7 := bestD6
        bestDir7 := bestDir6
        bestD6 := bestD5
        bestDir6 := bestDir5
        bestD5 := bestD4
        bestDir5 := bestDir4
        bestD4 := bestD3
        bestDir4 := bestDir3
        bestD3 := bestD2
        bestDir3 := bestDir2
        bestD2 := bestD1
        bestDir2 := bestDir1
        bestD1 := sumSq
        bestDir1 := d
    } else {
        if sumSq < bestD2 {
            bestD7 := bestD6
            bestDir7 := bestDir6
            bestD6 := bestD5
            bestDir6 := bestDir5
            bestD5 := bestD4
            bestDir5 := bestDir4
            bestD4 := bestD3
            bestDir4 := bestDir3
            bestD3 := bestD2
            bestDir3 := bestDir2
            bestD2 := sumSq
            bestDir2 := d
        } else {
            if sumSq < bestD3 {
                bestD7 := bestD6
                bestDir7 := bestDir6
                bestD6 := bestD5
                bestDir6 := bestDir5
                bestD5 := bestD4
                bestDir5 := bestDir4
                bestD4 := bestD3
                bestDir4 := bestDir3
                bestD3 := sumSq
                bestDir3 := d
            } else {
                if sumSq < bestD4 {
                    bestD7 := bestD6
                    bestDir7 := bestDir6
                    bestD6 := bestD5
                    bestDir6 := bestDir5
                    bestD5 := bestD4
                    bestDir5 := bestDir4
                    bestD4 := sumSq
                    bestDir4 := d
                } else {
                    if sumSq < bestD5 {
                        bestD7 := bestD6
                        bestDir7 := bestDir6
                        bestD6 := bestD5
                        bestDir6 := bestDir5
                        bestD5 := sumSq
                        bestDir5 := d
                    } else {
                        if sumSq < bestD6 {
                            bestD7 := bestD6
                            bestDir7 := bestDir6
                            bestD6 := sumSq
                            bestDir6 := d
                        } else {
                            if sumSq < bestD7 {
                                bestD7 := sumSq
                                bestDir7 := d
                            }
                        }
                    }
                }
            }
        }
    }
    s := s + 1
}

// ─── Vote channels from top-k neighbours ───
v1 = 0
if bestD1 < 999998.0 { v1 := bestDir1 }
v2 = 0
if bestD2 < 999998.0 { v2 := bestDir2 }
v3 = 0
if bestD3 < 999998.0 { v3 := bestDir3 }
v4 = 0
if bestD4 < 999998.0 { v4 := bestDir4 }
v5 = 0
if bestD5 < 999998.0 { v5 := bestDir5 }
v6 = 0
if bestD6 < 999998.0 { v6 := bestDir6 }
v7 = 0
if bestD7 < 999998.0 { v7 := bestDir7 }

keff = kIn
if keff < 1 { keff := 1 }
if keff > 7 { keff := 7 }
voteSum = 0.0
validK = 0
if keff >= 1 {
    if bestD1 < 999998.0 {
        voteSum := voteSum + v1
        validK := validK + 1
    }
}
if keff >= 2 {
    if bestD2 < 999998.0 {
        voteSum := voteSum + v2
        validK := validK + 1
    }
}
if keff >= 3 {
    if bestD3 < 999998.0 {
        voteSum := voteSum + v3
        validK := validK + 1
    }
}
if keff >= 4 {
    if bestD4 < 999998.0 {
        voteSum := voteSum + v4
        validK := validK + 1
    }
}
if keff >= 5 {
    if bestD5 < 999998.0 {
        voteSum := voteSum + v5
        validK := validK + 1
    }
}
if keff >= 6 {
    if bestD6 < 999998.0 {
        voteSum := voteSum + v6
        validK := validK + 1
    }
}
if keff >= 7 {
    if bestD7 < 999998.0 {
        voteSum := voteSum + v7
        validK := validK + 1
    }
}

M = 0.0
if validK > 0 { M := voteSum / validK }
G = 1.0 - abs(M)
C = abs(M) * (1.0 - G)

// ─── Signal conditions (both channels must agree) ───
buyState = M > marginThresh and G < agreeThresh
sellState = M < 0 - marginThresh and G < agreeThresh
buySig = buyState and not buyState[1]
sellSig = sellState and not sellState[1]

// ─── Signal markers (2D, inside conditionals) ───
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

// ─── Zone tints (bgcolor exception: conditional allowed) ───
if buyState { bgcolor("rgba(34,204,136,0.06)") }
if sellState { bgcolor("rgba(255,68,119,0.06)") }

// ─── Unconditional 2D rendering (oscillator channels) ───
plot(M, "Vote Margin", "#b48cff", 2, "separate")
plot(G, "Disagreement", "#ffd43b", 2, "separate")
plot(C, "Crispness", "#22cc88", 1, "separate")

// ─── 3D form: height = margin (bars3d columns), footprint = disagreement (scatter) ───
marginCol = M * 100 + close * 0.001
disagreeCloud = G * 100 + close * 0.001
plot3d(marginCol, "Vote Margin Column", "bars3d", "#b48cff", "separate")
plot3d(disagreeCloud, "Disagreement Footprint", "scatter", "#ffd43b", "separate")

// ─── 3D cones in the SAME pane ───
if buySig { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate") }

// Volume Session Value Model
// Session volume profile: POC + value area expansion, price leaving value is the signal.

profRows = input(24, "Profile Rows", 5, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(60, "Session Length Bars", 20, 200, 5)
showTerrain = input(true, "Show 3D Terrain")
showHist = input(true, "Show Value Histogram")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range ───────────────────────────────────────────────
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
rng = sessHigh - sessLow
if rng <= 0 { rng := close * 0.01 }
rowH = rng / profRows

// ─── Build row volumes from session bars ─────────────────────────
rowVol = array()
i = 0
while i < profRows {
    array.push(rowVol, 0.0)
    i := i + 1
}
k = 0
while k < sessLen {
    ck = close[k]
    vk = volume[k]
    idx = floor((ck - sessLow) / rowH)
    if idx < 0 { idx := 0 }
    if idx > profRows - 1 { idx := profRows - 1 }
    array.set(rowVol, idx, array.get(rowVol, idx) + vk)
    k := k + 1
}

// ─── POC: row with max volume ────────────────────────────────────
pocRow = 0
pocVol = array.get(rowVol, 0)
i = 1
while i < profRows {
    v = array.get(rowVol, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocPrice = sessLow + (pocRow + 0.5) * rowH
totalVol = array.sum(rowVol)
pocShare = 0.0
if totalVol > 0 { pocShare := pocVol / totalVol * 100 }

// ─── Value area: expand outward from POC ─────────────────────────
vaLow = pocRow
vaHigh = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profRows {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(rowVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < profRows - 1 { rightVal := array.get(rowVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < profRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHigh + 1) * rowH
valPrice = sessLow + vaLow * rowH
vaWidth = vahPrice - valPrice
vahVol = array.get(rowVol, vaHigh)
valVol = array.get(rowVol, vaLow)
terrVol = pocShare + vaWidth / rng * 10.0

// ─── Signals: price leaving value ────────────────────────────────
insideVA = close >= valPrice and close <= vahPrice
wasInside = insideVA[1]
buySig = close > vahPrice and wasInside
sellSig = close < valPrice and wasInside

if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }
if buySig { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d") }
if buySig { label3d(bar_index, vahPrice, "LEAVING", "#22cc88", 1.0, 1, "3d") }
if sellSig { label3d(bar_index, valPrice, "LEAVING", "#ff4477", 1.0, 2, "3d") }

// ─── Right-side value histogram (2D carries distribution) ───────
r = 0
while r < profRows {
    rv = array.get(rowVol, r)
    frac = 0.0
    if pocVol > 0 { frac := rv / pocVol }
    blen = floor(frac * 12.0)
    if showHist and blen > 0 {
        rtop = sessLow + (r + 1) * rowH
        rbot = sessLow + r * rowH
        hcol = "rgba(120,120,120,0.55)"
        if r >= vaLow and r <= vaHigh { hcol := "rgba(34,204,136,0.55)" }
        if r == pocRow { hcol := "rgba(255,212,59,0.75)" }
        box.new(bar_index + 1, rtop, bar_index + 1 + blen, rbot, hcol, hcol)
    }
    r := r + 1
}

// ─── 2D rails + value zone ───────────────────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(pocShare, "POC Share", "#ffd43b", 1, "separate")
fill(vahPrice, valPrice, "rgba(34,204,136,0.08)")
if insideVA { bgcolor("rgba(34,204,136,0.04)") }

// ─── 3D: value terrain + POC labelled rail + VA edge rails ───────
plot3d(terrVol, "Value Terrain", "surface", "#22cc88", "3d", 3)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 0)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)

// Fix 1: var lvl = highest(high, 20) froze at bar 0 — plain assignment recomputes every bar.
// Fix 2: close[-1] read a future bar — close > lvl removes lookahead.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) was Pine form — Oak uses positional (bar_index, price, title, style, color).
// Fix 4: plot3d RSI in pane "3d" draws oscillator as spiky forest over price — oscillators must use pane "separate".
// Fix 5: added missing 2D plots + paired 3D cones in same pane so model renders in both 2D and 3D without changing logic.
len = input(20, "Breakout Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 2, 50, 1)
osLvl = input(30, "Oversold Level", 2, 50, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, len)
r = rsi(close, rsiLen)
buySig = close > lvl
osSig = crossover(r, osLvl)
if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if osSig {
  plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "OS", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
plot(lvl, "Breakout Level", "#ffcc44", 1, "stepline")
plot(r, "RSI", "#b48cff", 1, "line", "separate")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

momLength = input(10, "Momentum Length", 5, 30, 1)
breakLength = input(20, "Breakout Length", 5, 50, 1)
volThreshold = input(1.0, "Volatility Threshold", 0.1, 5.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

vol = (high - low) / close * 100
mom = close - close[momLength]
upperBreak = highest(high[1], breakLength)
lowerBreak = lowest(low[1], breakLength)
volExp = vol > volThreshold
posMom = mom > 0
negMom = mom < 0
breakUp = crossover(close, upperBreak)
breakDown = crossunder(close, lowerBreak)
buySig = breakUp and posMom and volExp
sellSig = breakDown and negMom and volExp
failedBull = breakUp and volExp and negMom
failedBear = breakDown and volExp and posMom

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if failedBull {
    plotshape(bar_index, high, "Fail", "diamond", "#ffcc00")
}
if failedBear {
    plotshape(bar_index, low, "Fail", "diamond", "#ffcc00")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 1, "3d")
}
if failedBull {
    plotshape_3d(bar_index, high, "Fail", "diamond", "#ffcc00", markerSize, 0, "3d")
}
if failedBear {
    plotshape_3d(bar_index, low, "Fail", "diamond", "#ffcc00", markerSize, 1, "3d")
}
bgcolor(volExp and (breakUp or breakDown), "#22cc8822")
plot(upperBreak, "Upper Breakout", "#ff4477", 1, "stepline")
plot(lowerBreak, "Lower Breakout", "#22cc88", 1, "stepline")
plot3d(upperBreak, "Upper 3D", "line3d", "#ff4477", "3d", 0)
plot3d(lowerBreak, "Lower 3D", "line3d", "#22cc88", "3d", 1)

windX = input(0.0, "Wind Dir X", -1.0, 1.0, 0.1)
windY = input(1.0, "Wind Dir Y", -1.0, 1.0, 0.1)
windZ = input(0.0, "Wind Dir Z", -1.0, 1.0, 0.1)
windSpeedIn = input(15.0, "Wind Speed Knots", 0.0, 100.0, 0.5)
maxWind = input(50.0, "Max Wind Speed Knots", 10.0, 100.0, 1.0)
baseTail = input(1.0, "Base Tail Length", 0.2, 3.0, 0.1)
stretch = input(0.1, "Stretch Factor", 0.0, 0.5, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

priceWob = close - open
priceRange = high - low
dynX = windX + 0.02 * priceWob
dynY = windY + 0.02 * (close - close[1])
dynZ = windZ + 0.01 * priceRange
dynSpeed = windSpeedIn + (close - close[1])

mag = sqrt(dynX * dynX + dynY * dynY + dynZ * dynZ + 0.000000001)
nx = dynX / mag
ny = dynY / mag
nzRaw = dynZ / mag
nzC = nzRaw
if nzC > 1.0 {
    nzC = 1.0
}
if nzC < -1.0 {
    nzC = -1.0
}
absNz = abs(nzC)
rollRad = 0.0
rollDeg = 0.0

yawT = ny / (nx + 0.000000001)
absYawT = abs(yawT)
yawAtanDeg = 0.0
if absYawT <= 1.0 {
    yawAtanDeg = yawT / (1.0 + 0.28 * yawT * yawT) * 57.29578
}
if absYawT > 1.0 {
    invYaw = 1.0 / (yawT + 0.000000001)
    atanInvYaw = invYaw / (1.0 + 0.28 * invYaw * invYaw) * 57.29578
    if yawT > 0.0 {
        yawAtanDeg = 90.0 - atanInvYaw
    }
    if yawT <= 0.0 {
        yawAtanDeg = -90.0 - atanInvYaw
    }
}
yawDeg = yawAtanDeg
if nx < 0.0 {
    if ny >= 0.0 {
        yawDeg = yawAtanDeg + 180.0
    }
    if ny < 0.0 {
        yawDeg = yawAtanDeg - 180.0
    }
}
yawRad = yawDeg / 57.29578

denP = 1.0 - nzC * nzC
if denP < 0.0 {
    denP = 0.0
}
sqrtDen = sqrt(denP + 0.000000001)
tPitch = nzC / (sqrtDen + 0.000000001)
absTPitch = abs(tPitch)
pitchDeg = 0.0
if absTPitch <= 1.0 {
    pitchDeg = tPitch / (1.0 + 0.28 * tPitch * tPitch) * 57.29578
}
if absTPitch > 1.0 {
    invP = 1.0 / (tPitch + 0.000000001)
    atanInvP = invP / (1.0 + 0.28 * invP * invP) * 57.29578
    if tPitch > 0.0 {
        pitchDeg = 90.0 - atanInvP
    }
    if tPitch <= 0.0 {
        pitchDeg = -90.0 - atanInvP
    }
}
pitchRad = pitchDeg / 57.29578

tailLen = baseTail + dynSpeed * stretch
ratioRaw = dynSpeed / maxWind
speedRatio = ratioRaw
if speedRatio > 1.0 {
    speedRatio = 1.0
}
if speedRatio < 0.0 {
    speedRatio = 0.0
}

arrowColor = "#3388ff"
if speedRatio > 0.2 {
    arrowColor = "#55aacc"
}
if speedRatio > 0.4 {
    arrowColor = "#aa66aa"
}
if speedRatio > 0.6 {
    arrowColor = "#dd7744"
}
if speedRatio > 0.8 {
    arrowColor = "#ff8800"
}

arrowSize = tailLen * markerSize
if arrowSize > 3.0 {
    arrowSize = 3.0
}
if arrowSize < 0.2 {
    arrowSize = 0.2
}

above25 = dynSpeed > 25.0
wasAbove25 = above25[1]
crossAbove25 = above25 and not wasAbove25
buySig = crossAbove25 and dynZ > 0.5
sellSig = crossAbove25 and dynZ < -0.5
above40 = dynSpeed > 40.0
wasAbove40 = above40[1]
warnSig = above40 and not wasAbove40

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    model.longEntry("WindUp")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    model.shortEntry("WindDown")
}
if warnSig {
    plotshape(bar_index, high, "HighWind", "diamond", "#ff8800")
}

tipB = tailLen * nx * 10.0
tipP = tailLen * nzC * 10.0
arrow.new(0, 0, tipB, tipP, arrowColor, 2, "windArrow")

plot(dynSpeed, "Wind Speed Knots", "#3388ff", 2, "separate")
plot(tailLen, "Tail Length", "#ff8800", 1, "separate")
plot(yawDeg, "Yaw Deg", "#22cc88", 1, "separate")
plot(pitchDeg, "Pitch Deg", "#ff4477", 1, "separate")

plot3d(dynSpeed, "Wind Speed", "trail", "#3388ff", "separate", 0)
plot3d(tailLen, "Tail Length", "line3d", "#ff8800", "separate", 1)

if bar_index == 0 {
    plotshape_3d(0, 0, "Wind Arrow", "coneup", arrowColor, arrowSize, 0, "separate", pitchDeg, yawDeg, rollDeg)
}
if buySig {
    plotshape_3d(bar_index, low, "Wind Up", "coneup", "#22cc88", markerSize, 0, "separate", pitchDeg, yawDeg, rollDeg)
}
if sellSig {
    plotshape_3d(bar_index, high, "Wind Down", "conedown", "#ff4477", markerSize, 1, "separate", pitchDeg, yawDeg, rollDeg)
}
if warnSig {
    plotshape_3d(bar_index, high, "HighWind", "diamond", "#ff8800", markerSize, 2, "separate", pitchDeg, yawDeg, rollDeg)
}

flowBase = input(0, "Flow PSI Base", 0, 300, 1)
critThresh = input(150, "Critical Threshold", 50, 300, 1)
spinFactor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
numRings = input(3, "Num Shockwave Rings", 1, 5, 1)
ringSpeed = input(2.0, "Ring Expansion Speed", 0.1, 10.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

var discAngle = 0.0
var lockBars = 0.0

flowRange = abs(high - low) * 8.0 + abs(close - open) * 6.0
flowVol = volume / 10000.0
flow_psi = flowBase + flowRange + flowVol + bar_index * 0.01
spin_speed = flow_psi * spinFactor
locked = flow_psi > critThresh
overpressure_state = locked

if locked {
    discAngle := discAngle[1]
} else {
    discAngle := discAngle[1] + spin_speed
}

if locked {
    if locked[1] {
        lockBars := lockBars[1] + 1
    } else {
        lockBars := 0
    }
} else {
    lockBars := 0
}

spinLocked = 0.0 + lockBars * 0.0
spinEff = spin_speed * (1 - spinLocked) - spinLocked * 0 + (flow_psi - flow_psi[1]) * 0
discSpin = discAngle + flow_psi * 0.001
ringOff = 0.6 + numRings * 0.0
ring1 = 0.8 + lockBars * ringSpeed * 0.12 + 1 * ringOff
ring2 = 0.8 + lockBars * ringSpeed * 0.12 + 2 * ringOff
ring3 = 0.8 + lockBars * ringSpeed * 0.12 + 3 * ringOff
discPrice = flow_psi + 5.0

overAlert = crossover(flow_psi, critThresh)
releaseSig = crossunder(flow_psi, critThresh)

if overAlert {
    plotshape(bar_index, high, "OVER", "triangledown", "#ff4477")
}

if releaseSig {
    plotshape(bar_index, low, "Release", "triangleup", "#22cc88")
}

if overAlert {
    plotshape_3d(bar_index, high, "Over", "conedown", "#ff4477", 1.0, 2, "separate")
}

if locked {
    plotshape_3d(bar_index, discPrice, "Disc", "torus", "#33ccff", 1.0, 0, "separate", 90, discSpin, 0)
